<?php
namespace App\Http\Controllers\Api\Admin;
use App\Http\Controllers\Controller;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class MarketingDeliveryController extends Controller{
private const R=['channels'=>['table'=>'marketing_channels','prefix'=>'CHN'],'web-app-campaigns'=>['table'=>'marketing_placements','prefix'=>'PLC'],'paid-media'=>['table'=>'marketing_paid_campaigns','prefix'=>'MED']];
public function index(Request$r,string$resource):JsonResponse{$this->permit($r,'view');$c=$this->cfg($resource);$r->validate(['per_page'=>['nullable','integer','between:1,100'],'page'=>['nullable','integer','min:1'],'sort'=>['nullable',Rule::in(['created_at','name','code','status','impressions','spend'])],'direction'=>['nullable',Rule::in(['asc','desc'])]]);$q=$this->query($r,$resource);$rows=(clone$q)->orderBy($c['table'].'.'.($r->input('sort','created_at')),$r->input('direction','desc'))->paginate($r->integer('per_page',10));return response()->json(['data'=>['records'=>$rows,'summary'=>$this->summary($resource,$q)]]);}
public function show(Request$r,string$resource,string$id):JsonResponse{$this->permit($r,'view');$row=$this->find($resource,$id);abort_unless($row,404);$exceptions=DB::table('marketing_operational_exceptions')->where('resource_type',$resource)->where('resource_id',$row->id)->latest()->get();$activity=DB::table('activity_log')->where('subject_id',$row->id)->where('description','like',"marketing_{$resource}.%")->latest()->limit(30)->get();$events=$resource==='channels'?DB::table('marketing_channel_events')->where('channel_id',$row->id)->orderBy('metric_date')->get():collect();return response()->json(['data'=>['record'=>$row,'exceptions'=>$exceptions,'activity'=>$activity,'events'=>$events]]);}
public function store(Request$r,string$resource):JsonResponse{$this->permit($r,'create');return$this->save($r,$resource);}
public function update(Request$r,string$resource,string$id):JsonResponse{$this->permit($r,'update');$row=$this->find($resource,$id);abort_unless($row,404);return$this->save($r,$resource,$row->id);}
public function transition(Request$r,string$resource,string$id):JsonResponse{$this->permit($r,'update');$row=$this->find($resource,$id);abort_unless($row,404);$d=$r->validate(['action'=>['required',Rule::in(['activate','enable','pause','disable','connect','disconnect','schedule','complete','archive'])]]);$map=['activate'=>'active','enable'=>'healthy','pause'=>'paused','disable'=>'disconnected','connect'=>'healthy','disconnect'=>'disconnected','schedule'=>'scheduled','complete'=>'completed','archive'=>'archived'];DB::table(self::R[$resource]['table'])->where('id',$row->id)->update(['status'=>$map[$d['action']],'updated_by'=>$r->user()->id,'updated_at'=>now()]);activity('admin')->causedBy($r->user())->withProperties(['resource'=>$resource,'id'=>$row->id,'action'=>$d['action']])->log("marketing_{$resource}.status_changed");return response()->json(['data'=>['record'=>$this->find($resource,(string)$row->id)]]);}
private function save(Request$r,string$resource,?int$id=null):JsonResponse{$c=$this->cfg($resource);$rules=['name'=>[$id?'sometimes':'required','string','max:180'],'status'=>['nullable','string','max:30'],'configuration'=>['nullable','array']];if($resource==='channels')$rules+=['type'=>[$id?'sometimes':'required','string','max:40'],'provider'=>['nullable','string','max:100'],'business_unit'=>['nullable','string','max:80'],'market'=>['nullable','string','max:80'],'sender_account'=>['nullable','string','max:180'],'consent_scope'=>['nullable','string','max:80']];elseif($resource==='web-app-campaigns')$rules+=['surface'=>[$id?'sometimes':'required','string','max:50'],'type'=>[$id?'sometimes':'required','string','max:60'],'campaign_id'=>['nullable','exists:marketing_campaigns,id'],'audience_id'=>['nullable','exists:marketing_audiences,id'],'content_id'=>['nullable','exists:marketing_content,id'],'device'=>['nullable','string','max:50'],'market'=>['nullable','string','max:80'],'priority'=>['nullable','integer','min:0'],'starts_at'=>['nullable','date'],'ends_at'=>['nullable','date','after_or_equal:starts_at']];else$rules+=['platform'=>[$id?'sometimes':'required','string','max:50'],'objective'=>[$id?'sometimes':'required','string','max:50'],'ad_account'=>['nullable','string','max:160'],'campaign_id'=>['nullable','exists:marketing_campaigns,id'],'audience_id'=>['nullable','exists:marketing_audiences,id'],'content_id'=>['nullable','exists:marketing_content,id'],'budget'=>['nullable','numeric','min:0'],'starts_at'=>['nullable','date'],'ends_at'=>['nullable','date','after_or_equal:starts_at']];$d=$r->validate($rules);$creating=$id===null;$id=DB::transaction(function()use($r,$resource,$c,$d,$id,$creating){if(isset($d['configuration']))$d['configuration']=json_encode($d['configuration']);$d['updated_by']=$r->user()->id;$d['updated_at']=now();if($creating){$d['uuid']=(string)Str::uuid();$d['code']=$c['prefix'].'-'.now()->format('Y').'-'.str_pad((string)((DB::table($c['table'])->max('id')??0)+1),5,'0',STR_PAD_LEFT);$d['created_by']=$r->user()->id;$d['created_at']=now();$id=DB::table($c['table'])->insertGetId($d);}else DB::table($c['table'])->where('id',$id)->update($d);activity('admin')->causedBy($r->user())->withProperties(['resource'=>$resource,'id'=>$id])->log("marketing_{$resource}.".($creating?'created':'updated'));return$id;});return response()->json(['data'=>['record'=>$this->find($resource,(string)$id)]],$creating?201:200);}
private function query(Request$r,string$resource){$t=$this->cfg($resource)['table'];$q=DB::table($t)->whereNull($t.'.deleted_at');$fields=$resource==='channels'?['status','type','provider','business_unit','market','provider_sync']:($resource==='web-app-campaigns'?['status','surface','type','market','content_readiness','governance_status']:['status','platform','objective','delivery_health','tracking_health','governance_status']);foreach($fields as$f)if($r->filled($f)&&$r->input($f)!=='All')$q->where($t.'.'.$f,$r->input($f));if($r->filled('search')){$s='%'.$r->input('search').'%';$q->where(fn($x)=>$x->where($t.'.name','like',$s)->orWhere($t.'.code','like',$s));}return$q;}
private function summary(string$r,$q):array{$counts=(clone$q)->selectRaw('status,count(*) aggregate')->groupBy('status')->pluck('aggregate','status');$x=['total'=>(clone$q)->count(),'status_counts'=>$counts,'updated_at'=>now()->toIso8601String(),'exceptions'=>DB::table('marketing_operational_exceptions')->where('resource_type',$r)->where('status','open')->count()];if($r==='channels')$x['metrics']=['sent'=>(int)(clone$q)->sum('messages_sent'),'delivered'=>(int)(clone$q)->sum('delivered'),'engaged'=>(int)(clone$q)->sum('engaged'),'failed'=>(int)(clone$q)->sum('failed'),'suppressed'=>(int)(clone$q)->sum('suppressed'),'queued'=>(int)(clone$q)->sum('queue_count'),'providers'=>(clone$q)->distinct()->count('provider')];elseif($r==='web-app-campaigns')$x['metrics']=['impressions'=>(int)(clone$q)->sum('impressions'),'clicks'=>(int)(clone$q)->sum('clicks'),'conversions'=>(int)(clone$q)->sum('conversions'),'revenue'=>(float)(clone$q)->sum('attributed_revenue')];else$x['metrics']=['budget'=>(float)(clone$q)->sum('budget'),'spend'=>(float)(clone$q)->sum('spend'),'impressions'=>(int)(clone$q)->sum('impressions'),'clicks'=>(int)(clone$q)->sum('clicks'),'conversions'=>(int)(clone$q)->sum('conversions'),'revenue'=>(float)(clone$q)->sum('attributed_revenue')];return$x;}
private function find(string$r,string$id){$t=$this->cfg($r)['table'];return DB::table($t)->whereNull('deleted_at')->where(fn($q)=>$q->where('code',$id)->orWhere('uuid',$id)->when(ctype_digit($id),fn($x)=>$x->orWhere('id',(int)$id)))->first();}private function cfg(string$r):array{abort_unless(isset(self::R[$r]),404);return self::R[$r];}private function permit(Request$r,string$a):void{abort_unless($r->user()->hasPermission("marketing.{$a}")||$r->user()->hasPermission('admin.dashboard.view'),403);}}
